const strip = p => p.slice(p.indexOf('Project "SFO Live 3D"'))
const VTXT = `Check EVERY finding on the current files: fixed (show the evidence: re-run the check, numbers, at most one small render if essential), not fixed, or validly rejected. Hunt for regressions the fix introduced (the previous round's fixes caused 6 regressions -- assume there are some). Do not fix. Report residual findings (with severity) and key metrics.`

async function motion() {
  const fxRt = await agent(`${RN['fix2:realtime']}${strip(D['prompt:fix2:realtime'])}`, { label: 'fix2:realtime', phase: 'Fix', schema: RES })
  if (!fxRt) log('fix2:realtime returned nothing')
  const fx = { bridges: D['fix2:bridges'], realtime: fxRt }
  const prev = { bridges: D['verify1:bridges'], realtime: D['verify1:realtime'] }
  const ts = ['bridges', 'realtime']
  const vs = await parallel(ts.map(t => () => agent(`${BASE}\n\nTRACK: ${t}. Goal: ${TR[t].goal}\n\nINDEPENDENT VERIFIER (round 2). The fixer worked on these findings, in full:\n${J(prev[t].findings)}\n\nThe fixer's report, in full:\n${J(fx[t])}\n\n${VTXT}`, { label: `verify2:${t}`, phase: 'Verify', schema: FIND })))
  const vf = {}
  ts.forEach((t, i) => { vf[t] = vs[i]; if (vs[i]) log(`motion/${t} round 2: ${vs[i].findings.length} residual (${vs[i].findings.filter(f => f.severity !== 'minor').length} critical/major)`); else log(`verify2:${t} returned nothing`) })
  return { fx2_realtime: fxRt, verify2: vf, residual: Object.fromEntries(ts.map(t => [t, vf[t] ? vf[t].findings : null])) }
}

async function env() {
  const look = await agent(`${RN['env-review2:look']}${strip(D['prompt:env-review2:look'])}`, { label: 'env-review2:look', phase: 'Env review', schema: FIND })
  const rv = [D['env-review2:truth'], look]
  const findings = []
  rv.forEach((x, i) => { if (x) x.findings.forEach((f, j) => findings.push({ id: `${LENSES[i].key}2-${j + 1}`, ...f })); else log(`env-review2:${LENSES[i].key} returned nothing`) })
  log(`env review 2: ${findings.length} findings (${findings.filter(f => f.severity !== 'minor').length} critical/major)`)
  if (!findings.length) return { rv, findings, fx: null }
  const fx = await agent(`${ENVBASE}\n\nENVIRONMENT FIXER (round 2). The reviewers found (ALL findings, in full):\n${J(findings)}\n\nReviewer metrics: ${rv.filter(Boolean).map(x => x.metrics || '').join('\n')}\n\nFix every valid finding at its root cause; re-run the affected acceptance gates (numbers before / after); at most 3 small renders to confirm visual fixes (out/env/). Return a disposition for EVERY id.`, { label: 'env-fix2', phase: 'Env fix', schema: RES })
  return { rv, findings, fx, unreviewed_after_last_fix: true }
}

const res = await parallel([() => motion(), () => env()])
return { motion: res[0], env: res[1] }
